import {cancelOrder} from '@api-integration-aws/core/services';
import {formatResponse} from '@smart/feature-app/node';
import {ApiHandler} from 'sst/node/api';
import {middyfy} from '../../middleware/middy';
import {parseEvent} from '../../utils/parse-event';
import {EcomAuthenticatedHeadersSchema} from '../schema';
import {BodySafesForceSchema, BodySchema} from './schema';

const handler = ApiHandler(async (event) => {
  let bodyData, headersData;
  if (event.rawPath.includes(`/v1/orders/cancel-sf`)) {
    ({bodyData} = parseEvent(event, {
      BodySchema: BodySafesForceSchema,
    }));
    headersData = {
      'base-site-id': bodyData.baseSiteId,
    };
  } else {
    ({bodyData, headersData} = parseEvent(event, {
      BodySchema,
      HeadersSchema: EcomAuthenticatedHeadersSchema,
    }));
  }

  const response = await cancelOrder(bodyData, headersData);
  return formatResponse(200, response);
});

export const main = middyfy(handler);

