import {
  getUserOrder,
  getUserOrderHistory,
} from '@api-integration-aws/core/index';
import {formatResponse} from '@smart/feature-app/node';
import {ApiHandler} from 'sst/node/api';
import {middyfy} from '../../middleware/middy';
import {parseEvent} from '../../utils/parse-event';
import {
  GetOrdersHeadersSchema,
  GetOrdersHistoryQueryParamsSchema,
  GetOrdersPathParamsRequestSchema,
  GetOrdersQueryParamsRequestSchema,
  GetOrdersSFQueryParamsRequestSchema,
} from './schema';

const handler = ApiHandler(async (event) => {
  let queryParamsData, headersData, pathParamsData;
  if (event.rawPath.includes(`/v1/orders-sf`)) {
    ({queryParamsData} = parseEvent(event, {
      QueryParamsSchema: GetOrdersSFQueryParamsRequestSchema,
    }));
    headersData = {
      [`user-id`]: queryParamsData[`user-id`],
      [`base-site-id`]: queryParamsData[`base-site-id`],
    };
    pathParamsData = {
      orderId: queryParamsData[`orderId`],
    };
  } else {
    ({queryParamsData, headersData, pathParamsData} = parseEvent(event, {
      HeadersSchema: GetOrdersHeadersSchema,
      QueryParamsSchema: GetOrdersQueryParamsRequestSchema,
      PathParamsSchema: GetOrdersPathParamsRequestSchema,
    }));
  }

  const response = await getUserOrder(
    queryParamsData,
    headersData,
    pathParamsData,
  );

  return formatResponse(200, response);
});
const ordersHistoryHanlder = ApiHandler(async (event) => {
  const {queryParamsData, headersData} = parseEvent(event, {
    HeadersSchema: GetOrdersHeadersSchema,
    QueryParamsSchema: GetOrdersHistoryQueryParamsSchema,
  });

  const response = await getUserOrderHistory(queryParamsData, headersData);

  return formatResponse(200, response);
});

export const main = middyfy(handler);
export const ordersHistory = middyfy(ordersHistoryHanlder);

